{
  "name": "ponytail-opencode-v2",
  "version": "4.10.0",
  "description": "Lazy senior dev mode for AI agents. The best code is the code you never wrote.",
  "keywords": [
    "opencode-plugin",
    "opencode",
    "ponytail",
    "pi-package",
    "pi",
    "skills",
    "qoder"
  ],
  "license": "MIT",
  "author": {
    "name": "Dietrich Gebert",
    "url": "https://github.com/DietrichGebert"
  },
  "homepage": "https://github.com/cheesecodestudio/ponytail-opencode-v2",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/cheesecodestudio/ponytail-opencode-v2.git"
  },
  "bugs": {
    "url": "https://github.com/cheesecodestudio/ponytail-opencode-v2/issues"
  },
  "main": "./.opencode/plugins/ponytail.mjs",
  "exports": {
    ".": "./.opencode/plugins/ponytail.mjs",
    "./plugin": "./.opencode/plugins/ponytail.mjs"
  },
  "files": [
    "AGENTS.md",
    "hooks/",
    "skills/",
    ".opencode/",
    ".qoder/",
    ".qoder-plugin/",
    "pi-extension/",
    "scripts/uninstall.js",
    "scripts/cursor-hooks.js",
    "assets/",
    "LICENSE"
  ],
  "dependencies": {
    "@opencode/plugin": "^2.0.15"
  },
  "engines": {
    "opencode": ">=1.18.29 <2 || >=2.0.15 <3"
  },
  "pi": {
    "extensions": [
      "./pi-extension/index.js"
    ],
    "skills": [
      "./skills"
    ]
  },
  "publishConfig": {
    "access": "public"
  },
  "scripts": {
    "test": "node --test tests/*.test.js && npm test --prefix pi-extension && npm test --prefix ponytail-mcp"
  }
}

{
  "name": "ponytail-pi-extension-dev",
  "private": true,
  "type": "module",
  "scripts": {
    "test": "node --test ./test/*.test.js"
  }
}
